import {crc32} from 'node:zlib';
export const document=(name='test-skill')=>`---\nname: ${name}\ndescription: Synthetic resource QA\n---\nLOCAL_MOCK_SKILL_${name.toUpperCase()}\nUse assets/marker.txt and scripts/check.mjs only when authorized.\n`;
export function zipFiles(items){const local=[],central=[];let offset=0;for(const item of items){const name=Buffer.from(item.path),data=Buffer.from(item.data??''),crc=crc32(data),a=Buffer.alloc(30);a.writeUInt32LE(0x04034b50);a.writeUInt16LE(20,4);a.writeUInt32LE(crc,14);a.writeUInt32LE(data.length,18);a.writeUInt32LE(data.length,22);a.writeUInt16LE(name.length,26);local.push(a,name,data);const b=Buffer.alloc(46);b.writeUInt32LE(0x02014b50);b.writeUInt16LE(0x314,4);b.writeUInt16LE(20,6);b.writeUInt32LE(crc,16);b.writeUInt32LE(data.length,20);b.writeUInt32LE(data.length,24);b.writeUInt16LE(name.length,28);b.writeUInt32LE(((item.mode??0o100600)<<16)>>>0,38);b.writeUInt32LE(offset,42);central.push(b,name);offset+=30+name.length+data.length;}const directory=Buffer.concat(central),end=Buffer.alloc(22);end.writeUInt32LE(0x06054b50);end.writeUInt16LE(items.length,8);end.writeUInt16LE(items.length,10);end.writeUInt32LE(directory.length,12);end.writeUInt32LE(offset,16);return Buffer.concat([...local,directory,end]);}
export const skillZip=(name='alpha')=>zipFiles([{path:`${name}/skill.md`,data:document(name)},{path:`${name}/assets/marker.txt`,data:`SAFE_${name.toUpperCase()}_ASSET`},{path:`${name}/scripts/check.mjs`,data:`console.log('SAFE_${name.toUpperCase()}_SCRIPT')`}]);
